import React, { useState } from "react";
import "./index.css";

const CompiladorView = () => {
  const [codigo, setCodigo] = useState("");
  const [resultado, setResultado] = useState("");

  const handleCodigoChange = (e) => {
    setCodigo(e.target.value);
  };

  const handleAnalisarCodigo = async () => {
    try {
      const response = await fetch("http://localhost:8080/api/compilador/analisar", {
        method: "POST",
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify({ codigo }),
      });
      const data = await response.json();
      setResultado(JSON.stringify(data, null, 2));
    } catch (error) {
      setResultado('Erro ao conectar com o compilador.');
    }
  };

  return (
    <div className="container">
      <h1>Compilador Comida</h1>
      <div className="editor-container">
        <div className="line-numbers">
          {codigo.split("\n").map((_, i) => (
            <div key={i} className="line-number">{i + 1}</div>
          ))}
        </div>
        <textarea
          className="codigo-editor"
          value={codigo}
          onChange={handleCodigoChange}
          spellCheck={false}
        />
      </div>
      <button onClick={handleAnalisarCodigo}>Analisar Código</button>
      <h2>Resultado:</h2>
      <pre>{resultado}</pre>
    </div>
  );
};

export default CompiladorView;
